'use client';
import React from 'react';

import { Categories } from 'emoji-picker-react/primitives';
import * as Picker from 'emoji-picker-react/primitives';


// `categories` narrows the picker to one section; CategoryNav would hide
// itself with a single tab, so it is simply not rendered.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ComponentType<Picker.RootProps>;
  className?: string;
};

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  return (
    <div className="polaris-card">
      <h2 className="polaris-title">How did your first sale feel?</h2>
      <p className="polaris-subdued">Pick an emoji — we will add it to your milestone.</p>
      <RootComponent appearance="default"         className={className}
        categories={[Categories.SMILEYS_PEOPLE]}
        autoFocusSearch={false}
      >
        <Picker.Viewport>
          <Picker.List />
        </Picker.Viewport>
      </RootComponent>
      <div className="polaris-actions">
        <button type="button">Skip</button>
        <button type="button" className="polaris-primary">
          Save
        </button>
      </div>
    </div>
  );
}

/* The surrounding mock app (shared by every stack variant). */
.polaris-card {
  width: 380px;
  padding: 16px;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 1px 0 rgb(26 26 26 / 7%),
    inset 0 -1px 0 rgb(0 0 0 / 13%),
    inset 0 0 0 1px rgb(0 0 0 / 1%);
  color: #303030;
  font-family: Inter, -apple-system, BlinkMacSystemFont, 'San Francisco',
    'Segoe UI', Roboto, sans-serif;
  font-size: 13px;
}
.polaris-title {
  margin: 0 0 4px;
  font-size: 14px;
  font-weight: 650;
}
.polaris-subdued {
  margin: 0 0 12px;
  color: #616161;
}
.polaris-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
}
.polaris-actions button {
  padding: 6px 12px;
  border: 0;
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 0 0 1px #d4d4d4, 0 1px 0 #d4d4d4;
  color: #303030;
  font: inherit;
  font-weight: 550;
}
.polaris-actions .polaris-primary {
  background: #303030;
  box-shadow: none;
  color: #ffffff;
}

/* Shopify Polaris — inline "How did it go?" card: a single category
   (no tabs, no search, no titles) in a short grid, Polaris type and green
   primary button. */
/* Picker styles — the source of truth for every stack variant. */
.polaris-picker {
  --epr-bg-color: #f7f7f7;
  --epr-hover-bg-color: #ebebeb;
  --epr-focus-bg-color: #e3e3e3;
  --epr-category-label-height: 0px;
  --epr-emoji-size: 26px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 8px;
  height: 128px;
  border: 1px solid #e3e3e3;
  border-radius: 8px;
  background: var(--epr-bg-color);
}
.polaris-picker [data-epr-part='category-label'] {
  display: none;
}
.polaris-picker [data-epr-part='list'] {
  padding: 6px 0;
}
.polaris-picker [data-epr-part='emoji'] {
  border-radius: 8px;
}

